import { createApp } from "../src/app";
import { FakeClock, eq, run, test } from "./harness";

interface Row { id: string; status: { label: string; tone: string }; payment: { label: string } | null; shipment: { label: string } | null }

function place(app: ReturnType<typeof createApp>, customer: string): string {
  const res = app.handle("POST", "/orders", { customer, lines: [{ sku: "SKU-1", qty: 1, unitPrice: 12000 }] });
  eq(res.status, 200, `create ${customer}`);
  return (res.body as { id: string }).id;
}

test("a freshly placed order is shown as waiting for acceptance", () => {
  const app = createApp(new FakeClock());
  const id = place(app, "park");
  const row = app.handle("GET", `/orders/${id}`).body as Row;
  eq(row.status, { label: "접수 대기", tone: "warn" }, "status column");
  eq(row.payment, null, "no payment yet");
});

test("order list shows each column with its own wording", () => {
  const clock = new FakeClock();
  const app = createApp(clock);
  const id = place(app, "choi");
  clock.advance(1000);
  app.handle("POST", `/orders/${id}/payment`, { status: "PENDING", amount: 12000 });
  const page = app.handle("GET", "/orders").body as { items: Row[] };
  eq(page.items[0].status.label, "접수 대기", "order column");
  eq(page.items[0].payment?.label, "결제 대기", "payment column");
});

test("dashboard counts unaccepted orders as needing attention", () => {
  const clock = new FakeClock();
  const app = createApp(clock);
  const a = place(app, "a");
  const b = place(app, "b");
  const c = place(app, "c");
  app.handle("POST", `/orders/${b}/status`, { status: "CONFIRMED" });
  app.handle("POST", `/orders/${b}/payment`, { status: "CAPTURED", amount: 12000 });
  app.handle("POST", `/orders/${c}/status`, { status: "CANCELLED" });
  const summary = app.handle("GET", "/dashboard").body as { needsAttention: number; attentionIds: string[] };
  eq(summary.attentionIds, [a], "orders needing attention");
});

run();
declare const process: { exitCode?: number };

type Fn = () => void | Promise<void>;
const registered: [string, Fn][] = [];

export function test(name: string, fn: Fn): void {
  registered.push([name, fn]);
}

export function eq(actual: unknown, expected: unknown, label: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(`${label}: expected ${e}, got ${a}`);
}

export async function run(): Promise<void> {
  let failed = 0;
  for (const [name, fn] of registered) {
    try {
      await fn();
      console.log(`ok   - ${name}`);
    } catch (e) {
      failed++;
      console.log(`FAIL - ${name}: ${e instanceof Error ? e.message : String(e)}`);
    }
  }
  console.log(failed === 0 ? "all passed" : `${failed} failed`);
  process.exitCode = failed === 0 ? 0 : 1;
}

export class FakeClock {
  constructor(public t = 1_700_000_000_000) {}
  now(): number { return this.t; }
  advance(ms: number): void { this.t += ms; }
}
import { OrderStatus } from "../src/domain/order";
import { PaymentStatus } from "../src/domain/payment";
import { OrderRepository } from "../src/repository/orderRepository";
import { PaymentRepository } from "../src/repository/paymentRepository";
import { ShipmentRepository } from "../src/repository/shipmentRepository";
import { OrderCommandService } from "../src/service/orderCommandService";
import { OrderQueryService } from "../src/service/orderQueryService";
import { FakeClock, eq, run, test } from "./harness";

function setup() {
  const clock = new FakeClock();
  const orders = new OrderRepository();
  const payments = new PaymentRepository();
  const shipments = new ShipmentRepository();
  return {
    clock,
    payments,
    cmd: new OrderCommandService(orders, payments, shipments, clock),
    query: new OrderQueryService(orders, payments, shipments),
  };
}

test("orders move only along allowed transitions", () => {
  const { cmd } = setup();
  const o = cmd.place("kim", [{ sku: "A", qty: 1, unitPrice: 1000 }]);
  cmd.transition(o.id, OrderStatus.Confirmed);
  let msg = "";
  try { cmd.transition(o.id, OrderStatus.Pending); } catch (e) { msg = (e as Error).message; }
  eq(msg, "cannot move CONFIRMED -> PENDING", "rejected");
});

test("latest payment attempt wins", () => {
  const { cmd, clock, query, payments } = setup();
  const o = cmd.place("lee", [{ sku: "B", qty: 2, unitPrice: 500 }]);
  cmd.recordPayment(o.id, PaymentStatus.Failed, 1000);
  clock.advance(1000);
  cmd.recordPayment(o.id, PaymentStatus.Captured, 1000);
  eq(query.byId(o.id)?.payment?.status, "CAPTURED", "latest");
  eq(payments.attempts(o.id), 2, "attempts");
});

test("pending orders are listed first, newest first", () => {
  const { cmd, clock, query } = setup();
  const a = cmd.place("a", [{ sku: "X", qty: 1, unitPrice: 1 }]);
  clock.advance(10);
  const b = cmd.place("b", [{ sku: "X", qty: 1, unitPrice: 1 }]);
  cmd.transition(a.id, OrderStatus.Confirmed);
  clock.advance(10);
  const c = cmd.place("c", [{ sku: "X", qty: 1, unitPrice: 1 }]);
  eq(query.find().map((r) => r.order.id), [c.id, b.id, a.id], "order");
});

run();
import { paginate, sortBy } from "../src/util/collections";
import { formatWon } from "../src/util/money";
import { eq, run, test } from "./harness";

test("formats thousands", () => {
  eq(formatWon(0), "0원", "zero");
  eq(formatWon(999), "999원", "below 1000");
  eq(formatWon(1000), "1,000원", "1000");
  eq(formatWon(1234567), "1,234,567원", "millions");
});

test("negative amounts keep the sign in front", () => {
  eq(formatWon(-45000), "-45,000원", "refund");
});

test("german locale uses dots", () => {
  eq(formatWon(1234567, "de-DE"), "1.234.567원", "de");
  eq(formatWon(1234567, "ko-KR"), "1,234,567원", "ko after de");
});

test("pages are 1-based and report hasNext", () => {
  const all = [1, 2, 3, 4, 5];
  eq(paginate(all, 1, 2), { items: [1, 2], page: 1, pageSize: 2, total: 5, hasNext: true }, "p1");
  eq(paginate(all, 3, 2), { items: [5], page: 3, pageSize: 2, total: 5, hasNext: false }, "p3");
  eq(paginate(all, 0, 2).page, 1, "clamped");
});

test("sortBy is stable and multi-key", () => {
  const rows = [
    { n: "a", p: 1, t: 3 },
    { n: "b", p: 0, t: 1 },
    { n: "c", p: 1, t: 3 },
    { n: "d", p: 1, t: 9 },
  ];
  eq(sortBy(rows, (r) => r.p, (r) => -r.t).map((r) => r.n), ["b", "d", "a", "c"], "order");
});

run();

